/* Say: one line, BX, said by AX (0: narration). */
static void veng1_Say(uint16_t ax, uint16_t bx)
{
    fv_talk_buf = ax;
    CS_W(0x1E01) = bx;
    veng1_Talk(talk_buf);
    return;
}

